from collections import defaultdict

def dijkstra(V, E, edges, s, t):
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float('inf')] * V
    dist[s] = 0
    pq = [(0, s)]

    while pq:
        current_dist, u = heapq.heappop(pq)

        if current_dist > dist[u]:
            continue

        for v, weight in graph[u]:
            distance = current_dist + weight

            if distance < dist[v]:
                dist[v] = distance
                heapq.heappush(pq, (distance, v))

    return dist[t]

def count_shortest_paths(V, E, edges, s, t):
    min_distance = dijkstra(V, E, edges, s, t)
    if min_distance == float('inf'):
        return 0

    dp = [[0] * V for _ in range(min_distance + 1)]
    dp[0][s] = 1

    for d in range(1, min_distance + 1):
        for u in range(V):
            for v, weight in graph[u]:
                if dp[d - weight][u] > 0:
                    dp[d][v] += dp[d - weight][u]

    return sum(dp[min_distance])

