from collections import defaultdict

def dfs(graph, start, end, visited, path_count):
    if start == end:
        path_count[0] += 1
        return
    visited[start] = True
    for neighbor, _ in graph[start]:
        if not visited[neighbor]:
            dfs(graph, neighbor, end, visited, path_count)
    visited[start] = False

def floyd_warshall(graph, V):
    dist = [[float('inf')] * V for _ in range(V)]
    for i in range(V):
        dist[i][i] = 0
    for u, v, w in graph:
        dist[u][v] = w

    for k in range(V):
        for i in range(V):
            for j in range(V):
                if dist[i][k] != float('inf') and dist[k][j] != float('inf'):
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    return dist

def count_paths(graph, V, s, t):
    dist = floyd_warshall(graph, V)
    if dist[s][t] == float('inf'):
        return 0

    path_count = [0]
    visited = [False] * V
    dfs(graph, s, t, visited, path_count)
    return path_count[0]

